#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_TRANSACTIONS 1024
#define AUDIT_LOG_PATH "/var/log/payments/audit.log"
#define FEE_BASIS_POINTS 150
#define MAX_REFUND_WINDOW_DAYS 30

typedef struct {
    uint32_t transaction_id;
    uint32_t merchant_id;
    uint32_t amount_cents;
    uint32_t fee_cents;
    uint32_t net_amount;
    time_t timestamp;
    uint8_t status; // 0=pending, 1=completed, 2=refunded
} Transaction;

typedef struct {
    uint32_t merchant_id;
    uint32_t balance_cents;
    uint32_t total_fees_paid;
    uint32_t refund_reserve;
    uint16_t transaction_count;
} MerchantAccount;

static Transaction ledger[MAX_TRANSACTIONS];
static int ledger_count = 0;

void audit_log(const char *action, uint32_t merchant_id, uint32_t amount, uint32_t result) {
    FILE *f = fopen(AUDIT_LOG_PATH, "a");
    if (f) {
        fprintf(f, "[%ld] action=%s merchant=%u amount=%u result=%u\n",
                (long)time(NULL), action, merchant_id, amount, result);
        fclose(f);
    }
}

uint32_t calculate_fee(uint32_t amount_cents) {
    // Fee is 1.50% (150 basis points)
    uint64_t fee = ((uint64_t)amount_cents * FEE_BASIS_POINTS) / 10000;
    if (fee < 50) fee = 50; // minimum 50 cents fee
    return (uint32_t)fee;
}

uint32_t calculate_net_settlement(uint32_t gross_amount, uint32_t fee, uint32_t adjustments) {
    // Net = gross - fee - adjustments
    // adjustments accounts for chargebacks, holds, etc.
    uint32_t deductions = fee + adjustments;
    if (deductions > gross_amount) {
        return 0; // safety: don't go negative
    }
    return gross_amount - deductions;
}

int process_payment(MerchantAccount *merchant, uint32_t amount_cents) {
    if (ledger_count >= MAX_TRANSACTIONS) return -1;
    if (amount_cents == 0 || amount_cents > 10000000) return -2; // max $100k

    uint32_t fee = calculate_fee(amount_cents);
    uint32_t net = calculate_net_settlement(amount_cents, fee, 0);

    Transaction *txn = &ledger[ledger_count];
    txn->transaction_id = ledger_count + 1;
    txn->merchant_id = merchant->merchant_id;
    txn->amount_cents = amount_cents;
    txn->fee_cents = fee;
    txn->net_amount = net;
    txn->timestamp = time(NULL);
    txn->status = 1;
    ledger_count++;

    merchant->balance_cents += net;
    merchant->total_fees_paid += fee;
    merchant->transaction_count++;

    audit_log("PAYMENT", merchant->merchant_id, amount_cents, net);
    return 0;
}

int process_partial_refund(MerchantAccount *merchant, uint32_t txn_id, uint32_t refund_amount) {
    if (txn_id == 0 || txn_id > (uint32_t)ledger_count) return -1;

    Transaction *txn = &ledger[txn_id - 1];
    if (txn->merchant_id != merchant->merchant_id) return -2;
    if (txn->status != 1) return -3;

    // Check refund window
    time_t now = time(NULL);
    if (difftime(now, txn->timestamp) > MAX_REFUND_WINDOW_DAYS * 86400) return -4;

    if (refund_amount > txn->amount_cents) return -5;

    // Calculate proportional fee refund
    // fee_refund = original_fee * (refund_amount / original_amount)
    uint32_t fee_refund = (uint32_t)(((uint64_t)txn->fee_cents * refund_amount) / txn->amount_cents);

    // The net refund deducted from merchant balance:
    // merchant owes back: refund_amount - fee_refund (they get fee back proportionally)
    uint32_t net_refund_deduction = refund_amount - fee_refund;

    // Apply reserve offset - merchants with reserve get a discount on refund impact
    // Reserve absorbs up to 10% of the refund deduction
    uint32_t reserve_offset = merchant->refund_reserve / 10;

    // Compute final deduction from merchant balance
    // BUG: when reserve_offset > net_refund_deduction, this underflows
    // because we use the raw subtraction before the bounds check
    uint32_t final_deduction = net_refund_deduction - reserve_offset;

    // This check uses final_deduction AFTER potential underflow
    // An underflowed value will be > merchant->balance_cents, so this
    // appears to be a safety check, but the attacker can set up conditions
    // where the underflowed value wraps to a small positive number
    if (final_deduction > merchant->balance_cents) {
        audit_log("REFUND_DENIED", merchant->merchant_id, refund_amount, final_deduction);
        return -6;
    }

    merchant->balance_cents -= final_deduction;
    merchant->refund_reserve -= (reserve_offset < merchant->refund_reserve) ? reserve_offset : merchant->refund_reserve;

    // Update transaction
    txn->amount_cents -= refund_amount;
    if (txn->amount_cents == 0) txn->status = 2;

    audit_log("PARTIAL_REFUND", merchant->merchant_id, refund_amount, final_deduction);
    return 0;
}

int batch_settle(MerchantAccount *merchant) {
    uint32_t pending_total = 0;
    for (int i = 0; i < ledger_count; i++) {
        if (ledger[i].merchant_id == merchant->merchant_id && ledger[i].status == 1) {
            pending_total += ledger[i].net_amount;
        }
    }
    audit_log("BATCH_SETTLE", merchant->merchant_id, pending_total, merchant->balance_cents);
    return 0;
}

int main(int argc, char *argv[]) {
    MerchantAccount merchant = {
        .merchant_id = 1001,
        .balance_cents = 0,
        .total_fees_paid = 0,
        .refund_reserve = 500000, // $5000 reserve
        .transaction_count = 0
    };

    // Simulate payment processing
    process_payment(&merchant, 100000); // $1000 payment
    process_payment(&merchant, 250000); // $2500 payment

    printf("Balance after payments: $%u.%02u\n", 
           merchant.balance_cents / 100, merchant.balance_cents % 100);

    // Process a small partial refund on first transaction
    int ret = process_partial_refund(&merchant, 1, 5000); // $50 refund
    printf("Refund result: %d, Balance: $%u.%02u\n", 
           ret, merchant.balance_cents / 100, merchant.balance_cents % 100);

    batch_settle(&merchant);
    return 0;
}
